<script setup>
import { FIELD_LEVELS, configFromLevel } from '@/utils/cageGame/ballFlight'
import { fieldPayload } from '@/utils/cageGame/session'
const props=defineProps({modelValue:Object,disabled:Boolean})
const emit=defineEmits(['update:modelValue'])
function preset(id){emit('update:modelValue',fieldPayload(configFromLevel(id)))}
function set(key,value,fence=false){const field=structuredClone(JSON.parse(JSON.stringify(props.modelValue)));if(fence)field.fences[key]=Number(value);else field[key]=Number(value);field.levelLabel='Custom';emit('update:modelValue',field)}
</script>
<template><section class="field-setup"><h2>GAME MODE · FIELD SETUP</h2><p>Choose an age/competition level, then adjust dimensions to match your field.</p><label>Field level<select :value="modelValue.levelId" :disabled="disabled" @change="preset($event.target.value)"><option v-for="level in FIELD_LEVELS" :key="level.id" :value="level.id">{{ level.label }}</option></select></label><div class="dimensions"><label v-for="(label,key) in {lineL:'Left field',gapL:'Left gap',center:'Center field',gapR:'Right gap',lineR:'Right field'}" :key="key">{{ label }} (ft)<input type="number" min="50" max="600" :value="modelValue.fences[key]" :disabled="disabled" @input="set(key,$event.target.value,true)" /></label><label>Base paths (ft)<input type="number" min="30" max="100" :value="modelValue.basePathFt" :disabled="disabled" @input="set('basePathFt',$event.target.value)" /></label><label>Pitching distance (ft)<input type="number" min="20" max="70" step="0.5" :value="modelValue.pitchingFt" :disabled="disabled" @input="set('pitchingFt',$event.target.value)" /></label></div><p>Game outcomes are simulations based on exit velocity, launch angle, spray angle and field dimensions. Your measured cage results remain available in statistics.</p></section></template>
<style scoped>.field-setup{background:#171d30;border:1px solid #596078;border-radius:22px;padding:20px;margin:20px 0;color:white}h2{font-size:22px;font-weight:800}p{margin:12px 0;color:#ced5e4;font-size:14px}.dimensions{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:14px}input,select{display:block;width:100%;padding:12px;border-radius:10px;border:1px solid #78839c;background:#0e1424;color:white;margin:8px 0}label{font-size:14px}</style>
